import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  Index,
} from 'typeorm';

@Entity('business_code_registry')
@Index(['entityType', 'entityId'], { unique: true })
export class BusinessCodeRegistryEntity {
  @PrimaryGeneratedColumn('increment')
  id: number;

  @Column({ length: 100, unique: true })
  code: string;

  @Column({ length: 50 })
  entityType: string;

  @Column('uuid')
  entityId: string;

  @CreateDateColumn()
  createdAt: Date;
}

