@Entity('journal_entries')
export class JournalEntryEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  deviceId: string;

  @Column()
  accountDebit: string;

  @Column()
  accountCredit: string;

  @Column('decimal', { precision: 10, scale: 2 })
  amount: number;

  @Column()
  description: string;

  @Column({
    type: 'varchar',
    enum: AccountingStatus,
    default: AccountingStatus.DRAFT,
