  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  Index,
} from 'typeorm';

@Entity('customer_addresses')
export class AddressEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Index()
  @Column('uuid')
  customerId: string;

  /** Friendly label such as HOME, OFFICE, OTHER. */
  @Column({ type: 'varchar', default: 'HOME' })
  label: string;

  @Column({ type: 'varchar' })
  contactName: string;

  @Column({ type: 'varchar' })
  contactPhone: string;

  @Column({ type: 'varchar', nullable: true })
  contactEmail: string | null;

  @Column({ type: 'varchar' })
  line1: string;


  @Column({ type: 'varchar', nullable: true })
  line2: string | null;

  @Column({ type: 'varchar', nullable: true })
  landmark: string | null;

  @Column({ type: 'varchar', nullable: true })
  district: string | null;

  @Column({ type: 'varchar' })
  city: string;

  @Column({ type: 'varchar' })
  state: string;

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
} from 'typeorm';

@Entity('customers')
export class CustomerEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Public, human-friendly, immutable Customer ID (e.g. "BZK-8F3K9A2D").
   * Generated once at account creation and never changed.
   */
  @Column({ type: 'varchar', nullable: true, unique: true })
  customerId: string | null;

  @Column({ type: 'varchar', nullable: true, unique: true })
  customerCode: string | null;

  /**
   * Unique, shareable referral code (e.g. "BZRK-7QF3"). Generated once per
   * customer and used to attribute new sign-ups to a referrer.
   */
  @Column({ type: 'varchar', nullable: true, unique: true })
  referralCode: string | null;

  /** Referral code of the customer who invited this user, if any. */
  @Column({ type: 'varchar', nullable: true })
  referredByCode: string | null;


  @Column({ type: 'varchar', nullable: true, unique: true })
  phone: string | null;

  @Column({ type: 'varchar', nullable: true, unique: true })
  email: string | null;

  @Column({ type: 'varchar', nullable: true })
  firstName: string | null;

  @Column({ type: 'varchar', nullable: true })
  lastName: string | null;

  @Column({ type: 'varchar', nullable: true })
  name: string | null;

