@Injectable()
export class EmailService {
  private readonly logger = new Logger(EmailService.name);

  constructor(
    private readonly systemConfigRepo: SystemConfigRepository,
  ) {}

  async sendOtpEmail(email: string, code: string): Promise<boolean> {
    const smtpConfig = await this.getSmtpConfig();

    if (!smtpConfig.host) {
      this.logger.log(
        `[OTP] Email to ${email}: ${code} (no SMTP configured)`,
      );
      return true;
    }

    try {
      const nodemailer = require('nodemailer');
      const transport = nodemailer.createTransport({
        host: smtpConfig.host,
        port: smtpConfig.port,
        secure: smtpConfig.secure,
        auth: {
          user: smtpConfig.user,
          pass: smtpConfig.pass,
        },
      });

      await transport.sendMail({
        from: smtpConfig.from,
        to: email,
        subject: 'Your Bizrok Verification Code',
        text: `Your OTP code is: ${code}. It expires in 10 minutes.`,
        html: `
          <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
            <h2>Bizrok Verification Code</h2>
            <p>Your one-time password (OTP) is:</p>
            <div style="font-size: 32px; font-weight: bold; color: #2563eb; padding: 20px; background: #f3f4f6; border-radius: 8px; text-align: center; letter-spacing: 8px;">
              ${code}
            </div>
            <p style="color: #6b7280; margin-top: 20px;">This code expires in 10 minutes. Do not share it with anyone.</p>
          </div>
        `,
      });

