@Injectable()
export class PriceService {
  constructor(
    @Inject(IVariantRepositoryToken)
    private readonly variantRepo: IVariantRepository,
  ) {}

  async createInitialPrice(
    variantId: string,
    price: number,
  ): Promise<BasePriceEntity> {
    const basePrice: Partial<BasePriceEntity> = {
      variantId,
      price,
      effectiveFrom: new Date(),
      effectiveTo: null,
      version: 1,
    };
    return this.variantRepo.saveBasePrice(basePrice);
  }

  async updatePrice(
    variantId: string,
    price: number,
    effectiveFrom: Date,
  ): Promise<BasePriceEntity> {
    const currentPrice = await this.variantRepo.getCurrentPrice(variantId);
    const nextVersion = currentPrice ? currentPrice.version + 1 : 1;

    if (currentPrice) {
      currentPrice.effectiveTo = effectiveFrom;
      await this.variantRepo.saveBasePrice(currentPrice);
    }

    const nextPrice: Partial<BasePriceEntity> = {
      variantId,
      price,
      effectiveFrom,
      effectiveTo: null,
      version: nextVersion,
    };

    return this.variantRepo.saveBasePrice(nextPrice);
  }

