    await queryRunner.connect();
    try {
      await queryRunner.startTransaction();

      let row = await queryRunner.manager.findOne(BusinessCodeSequenceEntity, {
        where: { prefix: datePrefix },
      });

      if (!row) {
        row = queryRunner.manager.create(BusinessCodeSequenceEntity, {
          prefix: datePrefix,
          nextValue: 1,
        });
        await queryRunner.manager.save(row);
        await queryRunner.commitTransaction();
        return `${datePrefix}000001`;
      }

      const seq = row.nextValue;
