        console.log(
          `[QC] Procurement completed for device ${data.deviceId}. Ready for inspection.`,
        );
      },
    );
  }

  async submitQC(input: SubmitQCInput): Promise<QCAuditEntity> {
    const isPassed = input.functionalStatus.toUpperCase() === 'PASSED';
    const status = isPassed
      ? QCStatus.COMPLETED_PASSED
      : QCStatus.COMPLETED_FAILED;

    const qc: Partial<QCAuditEntity> = {
      ...input,
      status,
    };
    const saved = await this.qcRepository.save(qc);

    const needsRefurbishment =
      !isPassed ||
      (input.cosmeticGrade !== DeviceGrade.NEW &&
        input.cosmeticGrade !== DeviceGrade.GRADE_A_PLUS &&
        input.cosmeticGrade !== DeviceGrade.GRADE_A);

    this.eventBus.emit(EventNames.QC_COMPLETED, {
      deviceId: saved.deviceId,
      qcId: saved.id,
      cosmeticGrade: saved.cosmeticGrade,
      needsRefurbishment,
    });

