import { Resolver, Query } from '@nestjs/graphql';
import { HealthType } from './health.types';
import { checkPortOpen } from './health.utils';

@Resolver()
export class HealthResolver {
  @Query(() => HealthType)
  async systemHealth(): Promise<HealthType> {
    const dbHost = process.env.DB_HOST || 'localhost';
    const dbPort = Number(process.env.DB_PORT) || 5432;
    const redisHost = process.env.REDIS_HOST || 'localhost';
    const redisPort = Number(process.env.REDIS_PORT) || 6379;

    const [postgresRunning, redisRunning, esRunning] = await Promise.all([
      checkPortOpen(dbPort, dbHost),
      checkPortOpen(redisPort, redisHost),
      checkPortOpen(9200, 'localhost'),
    ]);

    return {
      database: postgresRunning ? { type: 'PostgreSQL', status: 'connected' } : { type: 'SQLite', status: 'connected' },
      redis: redisRunning ? { status: 'connected' } : { status: 'mock' },
      elasticsearch: esRunning ? { status: 'connected' } : { status: 'mock' },
    };
  }
}

