    @InjectRepository(AuditLogEntity)
    private readonly auditLogRepo: Repository<AuditLogEntity>,
  ) {}

  @Query(() => [AuditLogType], { name: 'auditLogs' })
  async getAuditLogs(
    @Args('entityName') entityName: string,
    @Args('entityId', { type: () => ID }) entityId: string,
  ): Promise<any[]> {
    const logs = await this.auditLogRepo.find({
      where: { entityName, entityId },
      order: { createdAt: 'DESC' },
    });
    return logs.map((log) => ({
      ...log,
      oldValues: log.oldValues ? JSON.stringify(log.oldValues) : null,
      newValues: log.newValues ? JSON.stringify(log.newValues) : null,
    }));
  }

  @Query(() => [AuditLogType], { name: 'allAuditLogs' })
  async getAllAuditLogs(): Promise<any[]> {
    const logs = await this.auditLogRepo.find({
      order: { createdAt: 'DESC' },
      take: 100,
    });
    return logs.map((log) => ({
      ...log,
      oldValues: log.oldValues ? JSON.stringify(log.oldValues) : null,
      newValues: log.newValues ? JSON.stringify(log.newValues) : null,
    }));
  }

  @Mutation(() => Boolean, { name: 'rollbackBatch' })
  async rollbackBatch(
    @Args('correlationId') correlationId: string,
  ): Promise<boolean> {
    const logs = await this.auditLogRepo.find({
      where: { correlationId },
    });
    if (logs.length === 0) return false;

